//! LaunchDaemon property list, generated by the helper itself
//! (`nox-helper --print-launchd-plist …`) so paths are XML-escaped by tested
//! code rather than by shell string building in the install script.

use std::path::Path;

fn xml_escape(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&apos;"),
            c if (c as u32) < 0x20 && c != '\t' => {}
            c => out.push(c),
        }
    }
    out
}

/// `RunAtLoad` (boot recovery) + `KeepAlive` on unsuccessful exit (relaunched
/// after a crash, which also runs the journal recovery). The helper exits 0
/// only on a stop request or a permanent misconfiguration it has logged, so
/// launchd does not relaunch it every 10 s into the same error.
pub fn plist(program: &Path, allowed_client: Option<&Path>) -> String {
    let mut args = vec![program.to_string_lossy().into_owned()];
    if let Some(c) = allowed_client {
        args.push("--allowed-client".into());
        args.push(c.to_string_lossy().into_owned());
    }
    let args: String = args
        .iter()
        .map(|a| format!("\t\t<string>{}</string>\n", xml_escape(a)))
        .collect();
    format!(
        r#"<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
	<key>Label</key>
	<string>{label}</string>
	<key>ProgramArguments</key>
	<array>
{args}	</array>
	<key>RunAtLoad</key>
	<true/>
	<key>KeepAlive</key>
	<dict>
		<key>SuccessfulExit</key>
		<false/>
	</dict>
	<key>ThrottleInterval</key>
	<integer>10</integer>
	<key>Umask</key>
	<integer>63</integer>
	<key>StandardErrorPath</key>
	<string>{log}</string>
</dict>
</plist>
"#,
        label = crate::LABEL,
        log = crate::LOG_PATH,
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn escapes_paths() {
        let p = plist(
            Path::new(crate::INSTALLED_BINARY),
            Some(Path::new("/Applications/A&B <x>.app/Contents/MacOS/nox")),
        );
        assert!(
            p.contains("<string>/Applications/A&amp;B &lt;x&gt;.app/Contents/MacOS/nox</string>")
        );
        assert!(p.contains("<string>--allowed-client</string>"));
        assert!(p.contains(crate::LABEL));
    }

    #[test]
    fn plutil_accepts_it() {
        let _ =
            std::io::Write::write_all(&mut std::io::stderr(), b"[trace] plutil_accepts_it start\n");
        let dir = std::env::temp_dir().join(format!("nox-plist-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let f = dir.join("t.plist");
        std::fs::write(
            &f,
            plist(
                Path::new(crate::INSTALLED_BINARY),
                Some(Path::new("/Applications/Nox \"β\".app/Contents/MacOS/nox")),
            ),
        )
        .unwrap();
        let out = std::process::Command::new("/usr/bin/plutil")
            .arg("-lint")
            .arg(&f)
            .output()
            .unwrap();
        let _ = std::fs::remove_dir_all(&dir);
        assert!(
            out.status.success(),
            "{}",
            String::from_utf8_lossy(&out.stdout)
        );
    }
}
